mapper.select:
SELECT t.id, t.ticket_no AS ticket_no, t.title AS title, r.name AS category_name, b.name AS building_name, t.room AS room, t.priority AS priority, t.status AS status, reporter.name AS reporter_name, assignee.name AS assignee_name, t.created_at AS created_at, t.updated_at AS updated_at FROM ticket t LEFT JOIN building b ON t.building_id = b.id LEFT JOIN repair_category r ON t.category_id = r.id LEFT JOIN sys_user reporter ON t.reporter_id = reporter.id LEFT JOIN sys_user assignee ON t.assignee_id = assignee.id
AND t.status = #{status}
AND t.category_id = #{categoryId}
AND t.building_id = #{buildingId}
AND t.priority = #{priority}
AND (t.ticket_no LIKE CONCAT('%', #{keyword}, '%') OR t.title LIKE CONCAT('%', #{keyword}, '%') OR t.room LIKE CONCAT('%', #{keyword}, '%'))
AND t.created_at >= #{createdFrom}
AND t.created_at <= #{createdTo}
AND (reporter.name LIKE CONCAT('%', #{reporterKeyword}, '%') OR reporter.username LIKE CONCAT('%', #{reporterKeyword}, '%'))
AND (assignee.name LIKE CONCAT('%', #{assigneeKeyword}, '%') OR assignee.username LIKE CONCAT('%', #{assigneeKeyword}, '%'))
AND t.reporter_id = #{reporterId}
AND t.assignee_id = #{assigneeId}
ORDER BY t.updated_at DESC, t.id DESC

SELECT reporter_id
FROM ticket
WHERE id = #{ticketId}

SELECT assignee_id
FROM ticket
WHERE id = #{ticketId}
